export default pattern<IframeSharedKanbanInput, IframeSharedKanbanOutput>(({
  input,
  output,
}) => {
  const state = new Writable<IframeStateData>(DEFAULT_STATE);
  const context = IframeContext({
    input,
    state,
    output,
  });

  return {
    [NAME]: "Iframe · Shared kanban",
    [UI]: (
      <div style={{ width: "100%", height: "760px" }}>
        <cf-iframe
          src={GUEST_HTML}
          $context={context}
          resourceKinds={{
            input: "readonly",
          } as const}
        />
      </div>
    ),
    state,
    output,
  };
});
